// D = numero di rette per schiera, INTERA: lo slider scatta all'intero al
// rilascio. La direttiva := si legge SOLO dallo scriptCode.
D := int(1,20);

float N = clamp(floor(D + 0.5), 1.0, 20.0);

// Le sezioni mesh sono testo statico: sono sempre 20. Le copie oltre N si
// collassano in un punto invece di essere disegnate.
float live = step(mesh, N - 0.5);

// SCHIERA: E < 0.5 -> solo sheet=+1. E >= 0.5 -> le due schiere alternate
// (mesh pari sheet=+1, mesh dispari sheet=-1), che si INCONTRANO: e' la maglia della
// doppia rigatura. Con due schiere le rette per schiera sono N/2.
float both = step(0.5, E);
float sheet = mix(1.0, 1.0 - 2.0 * mod(mesh, 2.0), both);

// Indice della retta DENTRO la propria schiera, e quante ce ne sono.
float idx = mix(mesh, floor(mesh * 0.5), both);
float cnt = mix(N, ceil(N * 0.5), both);

float a = 6.28318531 * idx / cnt;

// L lungo la retta: u in [-1,1] riscalato da B (mezza altezza del tratto).
float L = B * u;

// Punto sulla retta e frame costante (forma chiusa).
float ca = cos(a);
float sa = sin(a);
float k = 0.70710678;   // 1/sqrt(2)

float px = (A * ca - sheet * L * sa) * live;
float py = (A * sa + sheet * L * ca) * live;
float pz = (L) * live;

// n1 = (cos a, sin a, 0);  n2 = (-sin a, cos a, -sheet)/sqrt(2)
float cv = cos(v);
float sv = sin(v);

float nx = cv * ca + sv * (-sa * k);
float ny = cv * sa + sv * ( ca * k);
float nz =           sv * (-sheet  * k);

// Il corpo diventa il body di vec4 getRawPosition(...): il return DEVE essere
// vec4, con la quarta componente (coordinata 4D) a 0 per una superficie in R^3.
return vec4(
    px + C * nx * live,
    py + C * ny * live,
    pz + C * nz * live,
    0.0
);
